import math
import struct


def f32(x: float) -> float:
    """Round a Python float (a 64-bit double) to the nearest f32."""
    try:
        return struct.unpack("f", struct.pack("f", x))[0]
    except OverflowError:  # finite but past the f32 range: rounds to infinity
        return math.copysign(math.inf, x)


def sum32(xs: list[float]) -> float:
    """Sum a non-empty list the way reduce op=add does: start from the first element,
    add left to right, round to f32 after every add."""
    return sum(xs)
